<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { request, query, environment, type Page } from '../api'
import { money, dateTime } from '../domain.js'
import Modal from './Modal.vue'
import StatusBadge from './StatusBadge.vue'
const rows=ref<any[]>([]),total=ref(0),page=ref(1),status=ref(''),loading=ref(false),busy=ref(false),error=ref(''),success=ref('')
const selected=ref<any>(null),order=ref<any>(null),decision=ref('approved'),notes=ref(''),channel=ref('wechat'),keys=new Map<number,string>()
async function load(){loading.value=true;error.value='';try{const result=await request<Page>('/admin/refund-requests'+query({page:page.value,page_size:10,status:status.value}));rows.value=result.items;total.value=result.total}catch(err){error.value=(err as Error).message}finally{loading.value=false}}
async function open(row:any){selected.value=row;decision.value='approved';notes.value='';channel.value='wechat';error.value='';order.value=null;try{order.value=await request(`/orders/${row.order_id}`)}catch(err){error.value=(err as Error).message}}
async function review(){busy.value=true;error.value='';try{selected.value=await request(`/admin/refund-requests/${selected.value.id}/review`,{method:'POST',body:JSON.stringify({status:decision.value,notes:notes.value})});success.value='退款申请审核结果已保存';await load()}catch(err){error.value=(err as Error).message}finally{busy.value=false}}
async function refund(){if(busy.value)return;busy.value=true;error.value='';try{const id=Number(selected.value.id);if(!keys.has(id))keys.set(id,crypto.randomUUID());const result=await request(`/orders/${selected.value.order_id}/refund`,{method:'POST',body:JSON.stringify({request_id:id,amount_cents:Number(selected.value.amount_cents),reason:selected.value.reason,channel:channel.value,idempotency_key:keys.get(id)})});success.value=result.refund?.status==='succeeded'?'退款已由通道确认成功，佣金与利润状态已按服务器结果调整。':'退款请求已提交，等待真实通道确认结果。';selected.value=null;await load()}catch(err){error.value=(err as Error).message}finally{busy.value=false}}
onMounted(load)
</script>
<template><div class="page-heading"><div><h1>退款申请处理</h1><p>审核客户退款申请，通过后执行退款。成功状态必须来自渠道确认，不能以审核通过替代。</p></div><button class="button" @click="load">刷新申请</button></div><p v-if="error&&!selected" class="notice danger" role="alert">{{ error }}</p><p v-if="success" class="notice success" role="status">{{ success }}</p><section class="panel"><form class="filter-bar" @submit.prevent="page=1;load()"><select v-model="status" aria-label="退款申请状态"><option value="">全部状态</option><option value="pending">待审核</option><option value="approved">已批准待退款</option><option value="rejected">已驳回</option><option value="successful">退款成功</option></select><button class="button">查询</button><span class="record-count">共 {{ total }} 条申请</span></form><div class="table-scroll"><table><thead><tr><th>申请编号</th><th>订单 / 客户</th><th>申请金额</th><th>退款原因</th><th>状态</th><th>申请时间</th><th>操作</th></tr></thead><tbody><tr v-if="loading"><td colspan="7" class="empty">正在加载…</td></tr><tr v-else-if="!rows.length"><td colspan="7" class="empty">暂无退款申请</td></tr><tr v-for="row in rows" v-else :key="row.id"><td>#{{ row.id }}</td><td>订单 #{{ row.order_id }} / 用户 #{{ row.customer_id }}</td><td class="cell-title">{{ money(row.amount_cents) }}</td><td class="cell-truncate">{{ row.reason }}</td><td><StatusBadge :value="row.status" /></td><td>{{ dateTime(row.created_at) }}</td><td><button class="text-button" @click="open(row)">{{ ['pending','approved'].includes(row.status)?'处理申请':'查看结果' }}</button></td></tr></tbody></table></div><div class="pagination"><span>第 {{ page }} 页</span><button class="button small" :disabled="page<=1||loading" @click="page--;load()">上一页</button><button class="button small" :disabled="page*10>=total||loading" @click="page++;load()">下一页</button></div></section>
<Modal v-if="selected" :title="`退款申请 #${selected.id}`" wide @close="!busy&&(selected=null)"><p v-if="error" class="notice danger" role="alert">{{ error }}</p><dl class="detail-grid"><dt>关联订单</dt><dd>{{ order?.order_no||`#${selected.order_id}` }}</dd><dt>申请金额</dt><dd>{{ money(selected.amount_cents) }}</dd><dt>实收 / 已退款</dt><dd>{{ money(order?.paid_cents) }} / {{ money(order?.refund_cents) }}</dd><dt>申请原因</dt><dd>{{ selected.reason }}</dd><dt>当前状态</dt><dd><StatusBadge :value="selected.status" /></dd><dt>历史审核说明</dt><dd>{{ selected.review_notes||'—' }}</dd></dl><form v-if="selected.status==='pending'" id="refund-review-form" class="form-grid" style="margin-top:22px" @submit.prevent="review"><label><span>审核结果</span><select v-model="decision"><option value="approved">批准申请</option><option value="rejected">驳回申请</option></select></label><label class="span-all"><span>审核说明 *</span><textarea v-model="notes" rows="4" required /></label></form><template v-if="selected.status==='approved'"><p class="notice warning" style="margin-top:22px">审核通过尚未退款。真实通道未配置时会明确拒绝；开发测试通道不代表实际支付。部分退款成功后，剩余利润须重新复核。</p><label class="refund-channel"><span>执行退款的通道</span><select v-model="channel"><option value="wechat">微信支付</option><option value="alipay">支付宝</option><option v-if="environment.testPayments" value="test">开发环境测试通道</option></select></label></template><template #footer><button class="button" :disabled="busy" @click="selected=null">关闭</button><button v-if="selected.status==='pending'" form="refund-review-form" class="button primary" :disabled="busy">{{ busy?'正在审核…':'保存审核结果' }}</button><button v-if="selected.status==='approved'" class="button primary" :disabled="busy||!order" @click="refund">{{ busy?'正在执行退款…':'执行已批准退款' }}</button></template></Modal></template>
